from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

import pytest

from app.config import get_settings, set_test_overrides


@pytest.fixture
def data_dir(tmp_path: Path):
    """Isolated data directory with fresh databases."""
    path = tmp_path / "data"
    set_test_overrides(data_dir=str(path))
    from app.camera_sim import store

    store.init()
    yield path
    set_test_overrides()


def make_video(path: Path, seconds: float, fps: int = 10, size: str = "160x120", source: str = "testsrc") -> Path:
    """Synthetic H.264 test video generated by ffmpeg."""
    ffmpeg = get_settings().ffmpeg_bin
    if not (Path(ffmpeg).is_file() or shutil.which(ffmpeg)):
        pytest.skip(f"ffmpeg not found ({ffmpeg}) – set FFMPEG_BIN / FFPROBE_BIN or run the tests in Docker")
    subprocess.run(
        [get_settings().ffmpeg_bin, "-v", "error", "-y", "-f", "lavfi",
         "-i", f"{source}=duration={seconds}:size={size}:rate={fps}",
         "-c:v", "libx264", "-pix_fmt", "yuv420p", str(path)],
        check=True,
    )
    return path


@pytest.fixture
def video_factory(tmp_path: Path):
    def factory(name: str, seconds: float, **kw) -> Path:
        folder = tmp_path / "videos"
        folder.mkdir(exist_ok=True)
        return make_video(folder / name, seconds, **kw)

    return factory
